@@ -1752,0 +1752,8 @@
+
+    private static boolean isWhitespace(String text, int ix) {
+        if (ix < 0 || ix >= text.length()) {
+            return false;
+        }
+        int c = Character.codePointAt(text, ix);
+        return Character.isWhitespace(c);
+    }

